<script setup lang="ts">
import { onMounted, ref } from 'vue'; import type { SubscriptionSummary } from '@cyberboard/types'; import StatePanel from '@cyberboard/ui/components/StatePanel.vue'; import { getApiErrorMessage, portalApi } from '../api'
const loading=ref(true); const error=ref(''); const subscription=ref<SubscriptionSummary|null>(null); const revealed=ref(false); const copied=ref(false)
async function load(){loading.value=true;error.value='';try{subscription.value=await portalApi.getSubscription()}catch(cause){subscription.value=null;error.value=getApiErrorMessage(cause)}finally{loading.value=false}}
async function copy(){if(!subscription.value?.subscriptionUrl)return;await navigator.clipboard?.writeText(subscription.value.subscriptionUrl);copied.value=true;setTimeout(()=>copied.value=false,1800)}
onMounted(load)
</script>
<template><div class="portal-heading"><div><p class="eyebrow">配置分发</p><h1>我的订阅</h1><p>订阅状态和配置链接来自控制面 API。</p></div><button class="button button--secondary" type="button" :disabled="loading" @click="load">{{loading?'加载中…':'刷新'}}</button></div><StatePanel v-if="loading" title="正在加载订阅" description="正在读取订阅状态和访问凭证。"/><StatePanel v-else-if="error" title="订阅加载失败" :description="error" action-label="重试" @action="load"/><StatePanel v-else-if="!subscription" title="暂无订阅" description="服务端尚未返回当前用户的订阅。"/><template v-else><section class="portal-panel subscription-panel"><div class="subscription-status"><div><span class="muted">当前状态</span><h2><span class="health-dot"/>{{subscription.status}}</h2></div><div><span class="muted">到期时间</span><strong>{{subscription.expiresAt}}</strong></div><div><span class="muted">套餐</span><strong>{{subscription.plan}}</strong></div></div><div v-if="subscription.subscriptionUrl" class="token-box"><label>订阅链接</label><div class="token-row"><input :type="revealed?'text':'password'" :value="revealed?subscription.subscriptionUrl:'••••••••••••••••••••'" readonly/><button class="button" type="button" @click="revealed=!revealed">{{revealed?'隐藏':'显示'}}</button><button class="button" type="button" @click="copy">{{copied?'已复制':'复制'}}</button></div><small>令牌不会写入日志或普通页面 URL。</small></div><StatePanel v-else title="订阅链接暂不可用" description="控制面未返回 subscriptionUrl，请联系管理员。"/><div class="subscription-actions"><span class="muted">用量 {{(subscription.trafficUsedBytes/1e9).toFixed(1)}} / {{(subscription.trafficQuotaBytes/1e9).toFixed(1)}} GB</span></div></section></template></template>
